export const agents: Agent[] = [
  { name: 'Mark Bocado', slug: 'mark-bocado', role: 'Realtor', image: '/assets/reference/agents/Mark-Bocado.jpg', bio: 'Mark Bocado is a Houston area realtor that strives to provide the highest level of service to all of his clients. Mr. Bocado grew up locally; therefore, he is in tune with the small nuances that may not always be apparent. Mark excelled in school leading to a Master\'s degree and partnership with his wife, who is an entrepreneur. Then one day, the real estate bug really took hold of him, and he decided that this industry was his true passion. Mr. Bocado is a family man with 4 beautiful children and a highly supportive wife. He is an avid tennis and basketball player and understands that hard work can lead to achieving your goals. Real estate is a world dominated by relationships; therefore, Mark invests in making each interaction special and lasting. Attention to detail, efficiency, and solving problems are a highlight of his skill set. Mark endeavors to create, attain, and maintain connections that are optimized by communication and attentive interaction. He works with his team at 1st Texas Realtors to help each client achieve success and reach their goals.', phone: '281-836-0074', email: 'mark@1txrealtors.com' },
  { name: 'Matt Bradley', slug: 'matt-bradley', role: 'Realtor', image: '/assets/reference/agents/Matt-Bradley.jpg', bio: 'I was born in Abilene, Texas, and traveled to many East African nations. As part of my parents humanitarian efforts, I enjoyed the cultural lessons living abroad. In 1995, my family moved to the Clear Lake area and I attended Dobie High School in nearby Pasadena. Today, I am married with a daughter, work as a Realtor, read, play golf and general fitness enthusiast. There are so many places in the Clear Lake and Galveston Bay area to enjoy the outdoors and waterfront. Previously, I worked as a public educator and teacher in the Clear Lake area for many years, and subsequently became a realtor who enjoys making a curriculum out of the real estate process. As your Realtor, you can work with a family man with experience in diversity and a public educator when it comes to every decision important to your family.', phone: '832-654-9820', email: 'matt@1txrealtors.com' },
  { name: 'Nancy Estes', slug: 'nancy-estes', role: 'Realtor', image: '/assets/reference/agents/Nancy-Estes.jpg', bio: 'Nancy & Van Estes team up for the two-for-one Realtor experience specializing in the excitement of first time home buyers and new home sales. Nancy Estes was born and raised in Deer Park, Texas, graduated from Deer Park High School, and is considered a local real estate expert. In 1994, after wanting to spend more time with her husband, Nancy decided to assist Van in his real estate activities and found her calling like an epiphany, and became a Realtor. Van Estes has been an active licensed Realtor since 1991. Together, Van & Nancy total 29-years real estate experience. Nancy enjoys photography, crochet, community service and is a long time member of the Sagemont Church, yes, the one proudly displaying the 170-foot tall Cross next to I45. Please contact Nancy & Van for the husband and wife team of local real estate experts.', phone: '832-493-9398', email: 'nancy@1txrealtors.com' },
  { name: 'Jay Herder', slug: 'jay-herder', role: 'Realtor', image: '/assets/reference/agents/Jay-Herder.png', bio: 'Jay Herder grew up in the Friendswood and League City area, graduated from Friendswood High School and earned a Bachelors of Science degree in Hotel & Restaurant Management from the University of Houston. After living in downtown Houston for 6-years, Jay now resides in League City with his wife, Erin. Jay has successfully managed 14 different bars and restaurants and compares the process to home buying where every detail of the restaurant, or home, has to be addressed for presentation or value. Using a very detailed process, Jay strives to help educate his clients on every aspect of buying or selling homes. Jay & Erin, who manages a restaurant in Hobby Airport, enjoy a pastime of dining together at new restaurants and comparing the details and overall experience. As a casual carpenter, Jay also practices wood working and has worked on a number of pieces to furnish his and his friends\' homes.', phone: '832-790-7195', email: 'jay@1txrealtors.com' },
  { name: 'David Karstedt', slug: 'david-karstedt', role: 'Broker / Owner', image: '/assets/reference/agents/David-Karstedt.jpg', bio: 'David Karstedt was born in Houston, Texas, is a life-long resident of Bay Area Houston, attended Pasadena High School, studied Business at Sam Houston State University, and currently resides in El Lago. As a realtor and broker, David has over 20-years real estate experience in Bay Area Houston and voted Five-Star Real Estate Professional by Texas Monthly Magazine every year since 2010. This award goes to the Top 3% Realtors in the state of Texas and in recognition of service excellence. David Karstedt and wife Simone work as a team at 1st Texas Realtors, receive overwhelmingly positive reviews highlighting their exceptional responsiveness, deep knowledge and strong negotiation skills. The dynamic duo is known for personalized, patient service making the complex home buying and selling process smooth and enjoyable for their clients. They are praised for exceeding expectations, becoming trusted advisors and earning loyalty through high-quality service. Today, David is the owner and broker of 1st Texas Realtors, a family owned and operated real estate brokerage since 2004. My wife Simone Karstedt, a childhood friend since the second grade, is my full time partner in our business, you get twice the amount of excellent service and we do it all!', phone: '713-885-2228', email: 'david@1txrealtors.com' },
  { name: 'Simone Karstedt', slug: 'simone-karstedt', role: 'Realtor / Owner', image: '/assets/reference/1st-tx-realtors-couple-slider.png', bio: 'Simone Karstedt was born in Yorkshire, England, and also lived in Frankfurt, Germany, where her Mom met an American from Houston and they settled in Pasadena, Texas. Simone Karstedt and husband David work as a team at 1st Texas Realtors, receive overwhelmingly positive reviews highlighting their exceptional responsiveness, deep knowledge and strong negotiation skills. The dynamic duo is known for personalized, patient service making the complex home buying and selling process smooth and enjoyable for their clients. They are praised for exceeding expectations, becoming trusted advisors and earning loyalty through high-quality service. For Simone, real estate is about relationships and getting into other people\'s world, the personal time spent with clients while driving in the car, viewing homes, eating together and enduring the long process of buying or selling a home. Simone enjoys taking the frustration out of the process and even making it fun at times. Simone is involved in her church community where she greets regularly at worship and likes to host dinners for families at church. An avid reader and fitness enthusiast, Simone has owned a personal training studio in West University and helped open Fit Athletic Club in River Oaks, Houston. Other hobbies include snow skiing and river floating in the Texas hill country.', phone: '832-758-7408', email: 'simone@1txrealtors.com' },
  { name: 'William Machupa Jr.', slug: 'william-machupa-jr', role: 'Realtor', image: '/assets/reference/agents/William-Machupa.jpg', bio: 'William Machupa, Jr. has been an active licensed real estate agent in Texas since 2002. Originally from Buffalo, NY, he relocated to Houston in the late seventies and currently resides in League City with his wife Kalyn. After earning his Bachelors degree from the University of Houston in 1996 in biology, William discovered a wonderful career in the fitness industry as a professional personal fitness trainer. While meeting and motivating various professionals, he was encouraged to further his education in the real estate industry. In 2000, he attended real estate school and earned his license from the Texas Real Estate Commission. Now thriving in the industry for his second decade, William uses his personal skills to nurture relationships with buyers and sellers alike. His attention to detail and thorough customer service offer a sense of trust and client confidence to bring a contract to the closing table! Having lived and worked in the Clear Lake and surrounding areas for more than 25 years, William has seen the residential expansion of new neighborhoods and Master planned communities thrive.', phone: '832-969-4338', email: 'william@1txrealtors.com' },
  { name: 'Rhan Pruitt', slug: 'rhan-pruitt', role: 'Realtor', image: '/assets/reference/agents/Rhan-Pruitt.jpg', bio: 'Rhan Pruitt was born in Amarillo, Texas, grew up playing golf with his Grandpa and likes to celebrate birthdays with twin sister, Lisa. Starting at an early age, Rhan began his career in hospitality service in the restaurant business where he impressed a regular customer who convinced him to join his real estate title business. For 7-years, Rhan became an expert in real estate technology for business to business sales. With years of hospitality experience combined with real estate technology, becoming a realtor was a natural extension for Rhan. As a Realtor, Rhan (pronounced ran) is allowed to demonstrate his passion for taking care of people and apply his business acumen & entrepreneurial spirit. Hospitality and fiduciary is at the core of his service. Fairness, creativity, and efficiency are what he uses to make a transactions successful. 1st Texas Realtors is a Texas Monthly 5-Star recipient where Rhan is proud to post his license. With a BBA in Finance and prior successful careers in title company sales & management as well as restaurant management, Rhan has the education and experience to serve clients at a very high level. He can skillfully represent a first-time buyer, luxury homes, condos or townhomes, waterfront properties, short sales, and foreclosures. Past clients applaud his servant\'s heart, knowledge, and friendship during & after the transaction.', phone: '713-882-3683', email: 'rhan@1txrealtors.com' },
  { name: 'Daniel Rickert', slug: 'daniel-rickert', role: 'Realtor', image: '/assets/reference/agents/Daniel-Rickert.jpg', bio: 'My name is Daniel Rickert, and real estate is more than a profession for me — it\'s a calling to serve people during one of the most important decisions of their lives. I was born in San Diego, spent 11 years living in Arkansas, and eventually returned to Southern California, where I lived in both San Diego and Los Angeles for nearly 20 years. Along the way, I also completed a one-year missionary assignment in Pakistan — an experience that deepened my commitment to serving others with integrity, compassion, and excellence. I earned a Bachelor\'s degree in Biblical Studies and Psychology from San Diego Christian College and a Master of Divinity from Biola University. My background has shaped how I approach real estate: with careful listening, wise counsel, and a genuine desire to help people make confident decisions. Before becoming a Realtor, I spent nine years working in the home services industry — three years each in residential HVAC, home flooring, and home renovation. That hands-on experience gives me practical insight into the structure, systems, and potential of a home — knowledge I now use to guide my clients wisely when buying or selling. If you\'re considering buying or selling a home, I would be honored to interview for the opportunity to serve as your Realtor.', phone: '858-717-4347', email: 'daniel@1txrealtors.com' },
]

export const testimonials = [
  { quote: 'The experience and expertise of 1st Texas Realtors made the buying experience easy to navigate and gave me confidence through the entire process. They helped me find the right house and were available every step of the way.', author: 'Sam Curtis' },
  { quote: 'David Karstedt was amazing! He got things wrapped up in record speed. Great communication and a positive attitude. He made it all very easy. Thank you Mr. Karstedt. See you in a year!', author: 'Tammy Teel' },
  { quote: 'This real estate agent provided excellent service throughout my property search. They were responsive, knowledgeable, and very attentive to my requirements. They quickly identified suitable properties and guided me at every step of the process. Their negotiation skills were impressive and helped me secure a great deal. Communication was always clear and timely. I’m very happy with the outcome and would confidently recommend their services.', author: 'Carlis Payne' },
  { quote: 'We have used 1st Texas Realtors for several years for homes we’ve purchased and sold. David and Simone are very experienced, knowledgable, professional, patient, and are very supportive and encouraging throughout the process of buying and/or selling your home. I absolutely recommend 1st Texas Realtor for any real estate need you might have.', author: 'Don A' },
  { quote: 'We have worked with David and Simone for our real estate transactions for the last 20 years. In every scenario, they provide solid advice grounded in their extensive experience and knowledge of this area that helps us make sound financial decisions. We trust them fully, and are grateful for their excellence and partnership. You won’t find a team of better professionals or people. Highly recommend.', author: 'Julie Abram' },
  { quote: 'What an awesome experience! Working with David Karstedt was an absolutely fantastic experience from start to finish. He made what could have been a stressful process feel smooth, manageable, and even exciting. David was incredibly knowledgeable about the market and took the time to truly understand what we were looking for in a condo. He was always responsive, patient with our questions, and provided honest guidance that helped us make confident decisions. We never felt rushed or pressured—just fully supported every step of the way. What really stood out was his attention to detail and commitment to making sure everything went as smoothly as possible. From scheduling the property viewing to navigating paperwork and closing the lease , David stayed on top of everything and kept us informed throughout. Thanks to his expertise and dedication, we are now happily ready to settle into our new condo on the water, and we couldn’t be more grateful. We highly recommend David Karstedt to anyone looking for a reliable, professional, and genuinely caring realtor.', author: 'Matthew Smith' },
  { quote: 'David Karstedt is the savant of realtors. Hands-down. As long-standing clients, we can attest to his intellectual capacity to craft and close sophisticated contracts, quickly. Full honesty about your purchasing power is his weapon. David is professional, responsive, meticulous, and calculated in every facet of the transaction. He won’t waste your time, and you shouldn’t waste his. He’s conversant about the industry and that only stands to make you a savvier buyer/seller. The guy is pretty funny, too. I dare you to find out for yourself.', author: 'Melanie Schwemer' },
  { quote: 'Thank you so much 1st Texas Realtors for finding our Dream Home for us. You made the process go as smooth as silk. We anticipated so many problems as picky first time home buyers, but you made the entire process unbelievably easy and quick. You have so many outstanding resources and have an excellent knowledge of the real estate market. You helped us buy our new home and we trusted you 100%. We are now happily settled in and are so glad you were recommended from a family member. You were patient with our many special requirements and kept the communication going strong the whole way. We will be sure to recommend you to any future home buyers we know. Thank you from the bottom of our hearts.', author: 'Corey & Courtney Campbell' },
  { quote: 'Very pleased! Thank you.', author: 'Larry Monroe' },
  { quote: 'David and Simone were excellent to work with. As 1st time sellers, they helped us navigate every roadblock as smoothly as possible. Communication and availability is top notch. Highly recommend!', author: 'Jesse Green' },
  { quote: 'We have used 1st Texas Realtors and David Karstedt for multiple transactions over the years, including the sale and purchase of several homes. David has always been very insightful regarding current market conditions and extremely helpful as we considered different options and locations during our home searches. He is attentive and responsive to our needs, and he genuinely cares about his clients. We are truly thankful for David’s guidance, professionalism, and the integrity he brings to his work. It is a blessing to know someone whose faith is evident not only in what he says, but in how he serves others with honesty, care, and excellence. We thank God for placing people like David in our path and highly recommend David and 1st Texas Realtors to anyone looking for a trustworthy and faith-centered real estate professional.', author: 'Robert Hemminger' },
  { quote: 'I consider David Karstedt a friend and mentor concerning real-estate work. He has changed my perspective on becoming a successful landlord and better Christian. I would highly recommend working with David on any real-estate project you are considering. He has helped me through the anxiety of purchasing several homes.', author: 'Isaac Nelson' },
  { quote: 'Working with David and Simone has been a great experience. Their years of knowledge in the real estate industry really showed, and they guided me through the process with confidence and ease. They were professional, responsive, and truly cared about my best interest. I would highly recommend them to anyone looking for experienced and trustworthy agents!', author: 'Breece Phipps' },
  { quote: 'David handled pretty much everything for the sale of my house after I had already moved out of state. He let me know when and what I needed to do and made the whole process really easy. Highly recommend.', author: 'Billy Gatlin' },
  { quote: 'David is respectful to listen to what we were looking for in a home. He was considerate and mindful of our wish list items & then delivered several options to us for us to choose and he KNEW which house was going to be the humdinger for us! I am the type of person who prefers this approach across the board. He doesn’t try to show you things you didn’t ask for outside of your parameters without discussing it with you prior to see if that is the route you would like to go in. He was looking out for the best interest of my family by letting us know when would be the optimum time for us to put our house up for sale without having to figure out living quarters for our family of 5 should it sell before we moved into the new house. He was already doing the research of the area, to be ready for questions I may have or didn’t think to ask. Besides the nuts and bolts of real estate, which he has down, David is an all around honest to goodness God-fearing man that you’d want to have as your realtor.', author: 'Mic Loni' },
  { quote: 'As a first time homebuyer picking a real estate agent was a daunting decision but I know I made the right choice to work with 1st Texas Realtors. My agent, Matthew Bradley, was very knowledgeable and professional throughout the entire process and was a big part in making sure everything went as smoothly as possible. There was never any pressure to rush into a decision and he gave good detailed answers to my questions. He really went the extra mile when we had to send an offer on July 4th. It would have been easy and reasonable to hold off until after the holiday but Matt worked with me through the evening to make sure we had an offer I was comfortable with but still competitive enough to beat out other potential buyers. If I were to buy or sell a home in the future 1st Texas Realtors will be my first call.', author: 'Jan Villanueva' },
  { quote: 'Rhan is definitely the best realtor! We were out of state buyers and needed the knowledge and experience he showed us. Rhan Pruitt is a man of integrity that makes you feel confident he represents you. He is patient and proficient in procuring the property of your choice and answering any and all of your questions. He is persistent in tying any lose ends up too and keeping the process moving in a timely manner. It was a pleasure going through a usually stressful and tedious process with this realtor! Rhan can’t come with any higher recommendation and I am sure you won’t regret having him as your choice realtor in the 1st Texas Realtor office.', author: 'Amy Meyers' },
  { quote: 'David and Simone at 1st Texas Realtors are an absolute dream team!  From the moment we enlisted their help, they provided us with top-notch service and guidance every step of the way. As second-time homebuyers and first-time sellers, we were navigating uncharted waters, but David and Simone made the entire experience incredibly smooth and stress-free (as much as it can be). Their knowledge of the market was unparalleled, and they were ALWAYS available and willing to answer our questions and address any concerns we had. Communication with them was constant, which helped us stay informed and confident throughout the process. What truly stood out to us was their genuine patience and understanding. They took the time to  listen to our needs, concerns, and preferences, ensuring that we felt comfortable  and supported every step of the way. Most importantly, David and Simone went above and beyond to guide and counsel us, ensuring that we were making smart financial decisions. This personalized approach was exactly what we wanted, and their expertise helped us navigate the complexities of buying and selling with ease and allowed us to feel comfortable. We can confidently say that we will never work with anyone else in the future.  David and Simone have earned our trust and loyalty , and we will happily recommend them to anyone looking to buy or sell a home. Even our buyers’ realtor expressed admiration for their professionalism and kindness, highlighting just how exceptional this team truly is. Thank you, David and Simone, for exceeding our expectations and making our real estate journey a memorable and enjoyable one. You are truly the best in the business!', author: 'Krista Trippel' },
  { quote: 'I just wanted to take a moment and give a WELL DESERVED rating. I went looking for a realtor a little more than 6 months ago with very different circumstances than most people. I found Rhan Pruitt . I have to say, knowledgeable is just not strong enough a word for him. He is ABSOLUTELY OUTSTANDING at his job. Top notch professionalism, patient, punctual, disciplined, and an all around great person! He went out of his way, and I mean ABOVE AND BEYOND to get my family the home we wanted. I guess to sum this up, I went looking for a realtor and found that as well as much more, A FRIEND! He truly cares about his clients and in this world, that is a quality that most are missing. I hope this review reaches many many people, and I hope you do not hesitate in making him your realtor so you can also have the same experience myself and my family had buying our home. Thank you Rhan, and thank you for our house warming gifts. We loved them. You will always have a spot in our family!', author: 'Buddy Costlow' },
  { quote: 'I cannot express how thoroughly impressed and pleased I am to have gotten the chance to meet and work with Matt Bradley   through my home purchase process. From our first interaction, all the way through (and even after) closing he has been professional, knowledgeable, punctual in his responses, and has made the purchase of my first property very easy. Never once did I feel rushed or pressured, and I always knew that Matt had my best interests at heart. Matt truly displays a passion for finding the right home for people. I cannot recommend Matt and his team (namely  Drake ) highly enough!', author: 'Trey Kincade' },
  { quote: 'Thank you  Matt Bradley  for another great closing! Matt is proactive, high on communication and makes sure every detail is accounted for to ensure a smooth home buying experience. He’s great to work with and highly recommended!', author: 'Seth Saldivar' },
  { quote: 'This Realtor team is OUTSTANDING!! We are so happy we found them. We are first time home buyers and new to Texas. Simone and David were absolutely wonderful and they genuinely care about their clients. If you are thinking about contacting them.. just do it!! You will not regret it!!', author: 'Robert Mazza' },
  { quote: 'We had the pleasure of working with 1st Texas Realtors when buying our first home. From day one, our Agent Simone Karstedt was extremely responsive and had great suggestions for homes to view based on what we were looking for. All throughout the negotiations and closing she did anything to help, we highly recommend her! Anyone looking to purchase a home would be lucky to work with Simone.', author: 'Lenny Tucker' },
  { quote: 'We had a wonderful experience with the husband and wife team, David and Simone. They were knowledgeable and steered us in the right direction, but also very pleasant to spend time with. They are an incredible team and we loved working with them every step of the way.', author: 'Jennifer Meenehan' },
  { quote: 'This dynamic duo is the real deal, we have used them for several transactions and they have been fabulous. One particular time it took us time to find “the one” and they were incredibly patient as we toured home after home. They always make the process easy and fun as they are just wonderful people. They’ve become two of our favorite people to do business and life with.', author: 'Jennifer Youngdale Morgan' },
  { quote: 'My wife and I bought a home in League City, David and Simone were our realtors recommended by friends, and boy did they live up to the hype! David and Simone worked with my wife and I for months looking at a lot of houses, and they did not give up on us. Once our offer was accepted on the house we bought they were fast, very professional, and quick to respond to the many questions that we had. They are just kind, very responsive, sharp, humble, and all-around awesome people to work with. Anybody that asks us for advice about what realtor to use will get a recommendation to go with David and Simone from us!', author: 'Nathaniel Fisher' },
  { quote: 'David and Simone from 1st Texas are an amazing team! They have helped us purchase two homes and sell another home. They are quick to respond and so helpful along the way. They honestly make the home selling and purchasing process so smooth. We will continue to use their services in the future.', author: 'Danielle Carnighan' },
  { quote: 'David and Simone of 1st Texas Realtors represented the seller in a condominium that I purchased in Galveston. I have nothing but fantastic things to say about both of them and their company, true professionals, I would recommend them to anyone looking to list properties in the Clear Lake and Galveston area. If you are like me and happen upon them on the sell side, please know that they will do all they can to ensure the transaction progresses to close efficiently.', author: 'Austin Boatright' },
  { quote: 'David is fantastic! We actually talked to other realtors but after meeting him I knew instantly that I wanted him to sell our house. He is extremely knowledgeable, helpful and responds to emails and texts almost instantly. He is aggressive and assertive, because of him we were able to get more than expected for our house. We never had any trouble getting in touch with him and we always felt he truly had our best interests in mind. He’s very charismatic and takes a lot of the stress out of selling a house. He took the time to explain things and we never felt pressured or rushed. I hope we never have to buy or sell again but if we do, David will be our first call.', author: 'Shelley Brannon' },
  { quote: 'Wow, talk about amazing, this team is incredible! David & Simone are so friendly and knowledgeable and take the time to make sure you understand every step of the buying and selling process. I had questions that were immediately answered. We put in an offer to the house we fell in love with and found out that there were multiple offers. Simone and David fought for our offer and made the deal happen. Exceptional service and would recommend them to anyone and everyone that is in need of services. Thank you again Simone and David for making this process so smooth and easy!!', author: 'Julie Williams' },
  { quote: 'Rhan helped my family purchase our dream home. They were patient and explained every aspect of the selling and buying process. Their expert guidance made our dream come true! We didn’t think we could sell our house and quickly as we did, but with their guidance it only took 2 weeks! We put them through the ringer when trying to find our new home. We had many, detailed questions and many site visits, in addition to changes in what we wanted from location, price, and floorplans. They supported us through it all and never became impatient. I highly recommend them to any home buyer who wants to avoid the brand name companies that treat you like another number. We never felt pressured! Personalized service that made selling our home and buying our new one a breeze!', author: 'Jenny R.' },
  { quote: 'Rhan Pruitt not only helped my husband and I sell our home, but he also assisted us in purchasing another home that we absolutely loved! He is by far the BEST Realtor I have ever worked with. His professionalism, patience, knowledge, and efforts to keep us informed throughout the entire process definitely rank him far above all others.', author: 'Maelinda Dean-Peters' },
  { quote: 'First class service!! What a blessing to have Rhan as our realtor. We we’re building a home in a community that already had their own realtor and builders. Things get very stressful for a buyer trying to get everyone on the same page. When we had issues Ryan would get them addressed and always got back to us within a day. I very much appreciate is hard work, integrity , and fast friendly services. Highly recommend!', author: 'Jason & Heather Toth' },
  { quote: 'Excellent experience! Could not be more pleased! David and Simone helped make purchasing a home stress free and fun. They were always happy to take time to answer questions, give advice, and really guide my husband and I through this process. They helped us get into houses quickly and were extremely knowledgeable about homes, neighborhoods, and the area. We are incredibly thankful for everything they did for us and would highly recommend them to anyone who is looking to purchase a home.', author: 'Ruth Cooper' },
  { quote: 'David’s expertise was so appreciated as a first time homebuyer. He was able to advise me on resale value, but also let me have showings on the houses he advised against. His agent, Matt, showed us houses and was patient & thoughtful. He always gave us time to walk around and dream out loud while offering great suggestions. I love real estate and the both of them made my first homebuying really special. Thank you, David. One last time!', author: 'Morgan Mclish' },
  { quote: 'I was referred to 1st Texas Realtors by a friend and I couldn’t have had a better experience. David and Simone were very responsive, answered all of my questions, and helped walk me through my first home sale. The photographer they use to take pictures of the house was phenomenal and you can tell their entire team cares about your experience. We listed my house on a Friday afternoon, had multiple offers by the end of the weekend, and closed on the paper work 3 weeks from the date of listing. I can’t say enough great things about the team and I would highly recommend them to anyone looking for a realtor in the area.', author: 'Rachel Garcia' },
  { quote: 'David and Simone at 1st Texas Realtors have been taking great care of our real estate needs for almost 8-years. In the last year we have sold three properties and bought one. All of our properties had offers within a week!! David and Simone always go above and beyond with their first class service. We even sold a house while living in Australia which we thought was going to be a nightmare!! But David and Simone stepped up and made it all to easy for us. They are also some of the nicest, kindest people on the planet!!', author: 'Nicola Baker Ignatovich' },
  { quote: 'I worked with Rhan on purchasing my first home. He is very knowledgable, and accommodating. He shared plenty of information to me through out the process, and was very willing to work around my hectic schedule. The ability of being digital, via e-mail, text message, and talks over the phone made it very easy for me to further the process along whether home or on the road. But he doesn’t shy away from meeting up and talking face to face if the moment requires it. Would definitely recommend him, and his company to anyone else looking to purchase a home in the area.', author: 'Jeremy Chapin' },
  { quote: 'David and Simone are awesome!! They did an amazing job of walking us through the process as first time home buyers and provided tons of good advice with every step of the process. They were available and ready to answer any questions we had. It was a great experience and I’d recommend them to anyone.', author: 'Wiley Howard' },
  { quote: 'My wife and I were quite nervous about the selling of our home…for many reasons. David and Simone worked with us and helped us tremendously through the entire process!! They made it as easy for us and were very timely with their notices. We were very fortunate to have such outstanding realtors. We look forward to working with them for a buy or sale in the future!', author: 'James David Turnage' },
  { quote: 'Very knowledgeable and professional throughout the entire home buying process. They are available day or night with any questions or concerns. Highly recommended!', author: 'Rebecca Brooks' },
  { quote: '“I’m incredibly indebted to David and Simone Karstedt for their help in the process of purchasing my home in Friendswood. They make themselves available to you based on your schedule. In what I’ve noticed firsthand, David is attentive, highly intelligent, and in this business…his attention to detail is first-rate! I’m a total novice when it came to buying a home, but when I worked with David and Simone, they kept it simple and the transition was impeccably effortless and seamless! As a single father, I wanted something just for me and my son, and with their help, now I have it. They have been and will always be a blessing to my son and me.”', author: 'Dewayne Wheeland' },
  { quote: '“David is respectful to listen to what we were looking for in a home. He was considerate and mindful of our wish list items & then delivered several options to us for us to choose – and he KNEW which house was going to be the humdinger for us!!! I am the type of person who prefers this approach across the board. He doesn’t try to show you things you didn’t ask for outside of your perimeters without discussing it with you prior to see if that is the route you would like to go in. He was looking out for the best interest of my family by letting us know when would be the optimum time for us to put our house up for sale without having to figure out living quarters for our family of 5 should it sell before we moved into the new house. He was already doing the research of the area, to be ready for questions I may have or didn’t think to ask. Besides the nuts and bolts of real estate, which he has down, David is an all around honest to goodness God-fearing man that you’d want to have as your realtor.”', author: 'Micioni' },
  { quote: '“Could not ask for a better Real Estate Agent. David and his wife Simone are a great team and are great to work with. They are very prepared and knowledgeable. Even when we hit a snag with closing on a foreclosed home, David stayed on top of the situation, keeping us updated as much as possible. He made sure that we got the house and that everything was done correctly by the seller. I will definitely be using him again when we buy our next home.”', author: 'Neila Will' },
  { quote: '“We received fantastic service from David and Simone Karstedt! They are, hands down, the best in the business. Without being pushy, they gave my husband and I the best practical advice for purchasing our first home. Thank you both for your perfect direction and getting us into the home of our dreams! If you are looking for a home, call these two.”', author: 'Michelle McWhorter Ziglar' },
  { quote: '“Working with David and Simone Karstedt of 1st Texas Realtors on the purchase of our first home was a superb experience from beginning to end. They came very highly recommended, and did not disappoint. We would ask them to view a property the morning it was listed, and received a response within minutes. We were at the property as early as 8am that very morning. This attentiveness is what gave us the edge we needed to make great offers in the current highly competitive market. Through their experience both in the field and with other realtors, they were able to make things happen very smoothly and quickly, in addition to being very thorough, informative, and encouraging every step of the way. This team is amazing!”', author: 'Vanessa Galaz' },
  { quote: '“Simone and David were the best to work with. We had a realtor before them and she wasn’t doing what we thought she should and being first time home buyers were unsure about the home buying process and felt that we needed someone different. It was the best decision we made going with Simone and David! Their knowledge of the area and the entire process was priceless. Even when we had a hiccup at closing and had to extend our contract they took care of everything and made us feel at ease during the whole process. They were always available for questions and very quick to respond. I will definitely be using them again when we decide to move again.”', author: 'Neil Williams' },
  { quote: '“We had a great experience working with David and Simone. They definitely put their customers first and have integrity! They’re the only realtors we’ll use!”', author: 'John & Shirley Votaw' },
  { quote: '“I am in the insurance business and when a client tells me that they need assistance with a real estate purchase or sale, the first and only name that I suggest is 1st Texas Realtors. David and Simone Karstedt are careful and attentive. They do everything required, and more, to make sure each transaction goes smoothly for the buyer or seller. Keep up the great work!”', author: 'Michael Thomas' },
  { quote: '“I’ve been using 1st Texas Realtors for my Real Estate needs for years now. I could not imagine using anyone else! I refer everyone I know to David and Simone because I know they will be taken care of. This is a top notch run business with a personal touch. After working with them you will feel like family.”', author: 'Jonathan Morrison' },
  { quote: '“Extremely nice and easy to work with, Simone listened to what we were looking for and matched up perfect houses. She did not try and push anything upon us and was available to reach by phone and email any time we needed her.” “Simone is amazing!!! She was available all hours and willing to do whatever she could to help me find the right house. Her knowledge on the market and the area where I was looking was incredible. I will definitely be using her in the future and will be recommending her to all of my friends and family.” “We had a wonderful experience working with Simone and I look forward to referring her business in the future!” “As the owner of one of Texas largest home inspection companies, I am in contact with literally hundreds of Realtors. David and Simone Karstedt truly set the bar on all levels of knowledge, professionalism and standards of excellence. The knowledge they bring to their clients during the purchase process is the best you will find anywhere. I rarely give reviews unless earned and well deserved. From an inspectors perspective, I have a front row seat in watching this team go to bat for their clients to ensure they are fully protected. Great company to work with.”', author: 'Greg Bryan' },
  { quote: '“As I was in my kitchen this afternoon, I was reminded of how thankful I am for my awesome kitchen and beautiful home. God has provided amazingly for me. You discovered this house and knew that I would love it. Thank you for doing that! Thank you for finding me this home that I love so, so much! As I thought of all of these things, they led me to pray for you, your marriage, your son, your business, etc. I pray that God blesses you and grows you to be more and more like Him.”', author: 'Leslie Sabbann' },
  { quote: '“Thank you, David, Simone, and Joel Redmond for the gift. I hope you realize what you have done for my family. Because of your expertise, you fought the battles no one would fight, from handling of the sale of our home to the transaction of buying our new home. There is no one in the world I would seek for help. With countless hours negotiating two transactions, you pulled through every time. My family sleeps soundly in the perfect home tonight because of you. My business prospers on top of that. Thank you for being awesome and for being an integral part of the Guthrie family happiness.”', author: 'Jerremy Guthrie' },
  { quote: '“1st Texas Realtors Rocks, David and Simone Karstedt are the best. We have had the best experience with them and they really worked hard for us. And believe me they had the utmost patient with us! They not only helped us, they helped my daughter and her husband buy their first home. 1st Texas Realtors did a fantastic job selling our house. Love them… What a blessing!”', author: 'Dan & Phyllis Gross' },
  { quote: '“1st Texas Realtors used creative marketing specialized to our house, and the ideal buyer was found. All around, a great experience, and I would highly recommend 1st Texas Realtors to everyone we know.”', author: 'Tim Brandt' },
  { quote: '“Our interactions with David and Simone were never about the buying or selling of real estate, but about finding a home for my family! They truly care about their clients and follow through to the end. Their relationship with you throughout the experience is paramount!”', author: 'Sean & Laura Haug' },
  { quote: '“1st Texas Realtors. Excellent experience in our search!”', author: 'James & April Mulkey' },
  { quote: '“My experience with 1st Texas Realtors was very good. They were very clear with the process and the paperwork of the rental home. They kept us updated on everything as soon as it happened. They understood our needs and treated us as a valued customer. We would recommend them!!!”', author: 'Trina Hall' },
  { quote: '“I have had bad experiences in the past with buying & selling houses. 1st Texas Realtors has been great. I felt that I was in good hands.”', author: 'Mat & Noel Ann Wright' },
  { quote: '“I first began working with David in 2006 when he helped me find a wonderful home in Friendswood. It was perfect for my family, giving us water access in just a few minutes. David made this process seamless, and his professionalism and knowledge of real estate allowed me to enjoy house hunting. When I began looking for a home on the water in 2011, I contacted David immediately. He had my Friendswood house rented in less than a week. In these tough economic times, he was able to help me with a very unique financial plan, allowing me to purchase my waterfront home. I recommend David and his team to anyone looking for expert service and advice in the local real estate market.” “This was our first time to buy a house and I couldn’t be happier! Simone was very easy to work with and was very helpful. I would highly recommend using her skills when it comes to buying a house. If/when we decide to sell and go elsewhere, I will be giving her a call! Thanks again for the help!!” “We were referred to David & Simone with 1st Texas Realtors through a friend who couldn’t say enough good things about them. Having worked with them ourselves now, we couldn’t agree more. They helped us find exactly the home we were looking for in League City. As a new family to the area, we are so incredibly grateful that we had them working with us through this process. Everything was smooth and drama-free, exactly as we wanted it to be! We were on a tight timeline to find a home to purchase, and they where available, thorough and helpful from our very first phone call. They was always available by phone, email or text, and promptly sent us new listings when they became available. They were incredibly flexible with our work schedules in terms of showing homes in the late afternoon, early evening or weekends, but also didn’t hesitate to suggest to us if he thought we needed to see something sooner. They was always available to show us a new listing, or to return for a second look. Communication with them was easy and prompt. There are so many things that we appreciated about working with them. They was incredibly knowledgeable – about homes in general in the League City and surrounding markets specifically. They would non-judgmentally point out both positive and negative features of a home, but we always felt as if they was leaving the ultimate judgment to us. They are good natured and easy to be around, always professional but pleasant. They are very accommodating when we would need to bring our kids or extended family with us to showings, even though I know that can be distracting. Once we found the right home, we again were so blessed of their expertise. They provided us the perfect balance of there suggestions for what would be a strong offer for this home in this market, while never pressuring us and always making us feel like the ultimate decision was ours. Once under contract, they remained extremely helpful and responsive to all our “first-time” questions and helped make sure that everything proceeded as expected. In the end, we found a great place in about a month and had closed less than 30 days after that. We can’t recommend 1st Texas Realtors highly enough, and will definitely work with them again in the future if the opportunity arises.”', author: 'Jason and Tracy Taylor' },
  { quote: 'David & Simone found the perfect house for us. We cannot say enough great things about the experience buying our new home. David worked patiently & tirelessly during the search process for the location we really wanted. During the purchase they were always just a phone call or text away answering the questions we had. If you want a fantastic home buying experience with true professionals, then call 1st Texas Realtors. After the sale they made sure we had all the support we needed moving in. We cannot thank David & Simone enough!!! Thank you 1st Texas Realtors!!!', author: 'Matthew Siebenlist' },
  { quote: 'We had the most wonderful experience with, husband and wife team, David and Simone Karstedt. They were not only knowledgeable and helped steer us in the right direction, but they were also so pleasant to spend time with. They are an incredible team and we loved working with them every step of the way.', author: 'Jennifer M.' },
  { quote: 'My experience with 1st Texas Realtors included both selling my home, and buying my next home. I worked closely with David and Simone throughout the process. I listed my home for sale with 1st Texas Realtors, with the goal of buying a new home once my current home would eventually sell. From the professional, friendly service, to the constant (almost daily) communication with them, this company exceeded our expectations in every way – every step of the way. I’ve used realtors before and NO ONE comes close to how much 1st Texas Realtors really cares, and OVER-DELIVERS to you. This company is very knowledgeable, informed us of current market trends, as well as how to ‘best’ present our home – AND – planned how to buy my next home at the same time using their invaluable ‘network’ of professionals. Little did I know, using 1st Texas Realtors real estate network, and extensive expertise, my home was listed for sale, and I had an accepted offer. I then made an offer on my next home by utilizing 1st Texas Realtors and their network, and again, their negotiations on my behalf sealed the deal. I can honestly say, if it was not for David and the staff at 1st Texas Realtors, none of this would have happened, and happen so flawlessly. 1st Texas Realtors is a company who truly cares about you. They are the REAL DEAL. Simply put, if you want your dreams to come to fruition, use this company for ALL of your real estate needs – you will NOT be disappointed.', author: 'Jeremy G.' },
  { quote: 'David and Simone of 1st Texas Realtors are excellent at what they do. They recently sold our house and found us a new one. The process was truly more enjoyable with them in our corner. David knows how to make things happen and keeps all the parties involved on task and on time, He brings years of experience with him and it shows. We were continually kept up to speed about the selling process and on the buying end of things. Communication is great with these folks, as I rarely had to wait more than a few minutes for David to return texts, calls, etc. Good realtors are worth their weight in gold and the Karstedt’s are no exception! I will recommend them to anyone I know who is looking to buy or sell.', author: 'Brad M.' },
  { quote: 'Had the best experience buying our first home 2 years ago! Not only did David have our best interest in mind it was a pleasure to work with such an honest & outgoing person. His years in the business made it very knowledgeable for us, without him I don’t think we would be home owners! Thank you David for all you did for us & having the best & easiest experience buying our first home!', author: 'Bradlee & Stevie Fussell' },
  { quote: 'In November last year my husband and I made the decision to put our larger family home on the market. We had found a waterfront townhouse that we absolutely fell in love with and decided to try our luck in hopes of a quick buy and sale in a somewhat sluggish Houston housing market. With great knowledge, enthusiasm and confidence David and Simone began their realtor “magic”. Every detail handled with excellence, from the photo presentation display of our home, to the expert counsel of buying/selling negotiations. Much to our delight, both our buy and sale were incredibly and profitably complete in under two weeks! Without question, these are honest, kind, and exceptionally hard working people that give extraordinary service to their clients and clearly, they know how to get the job done right!', author: 'Lori V.' },
  { quote: 'We used 1st Texas Realtors 4 years ago for the purchase of our first home and felt completely comfortable and informed throughout the entire process. Now with the news of a coming new addition to our family we called David again to find us more space. After searching several options we found the home we wanted, a new construction home that was very close to completion. David worked quickly and negotiated a contract for our house in just over a week! David and Simone are honest, hard-working, and knowledgeable realtors that run their business with integrity. I wouldn’t consider using anyone else.', author: 'Brian A.' },
  { quote: 'When I first met David and Simone I instantly knew that I was in good hands. 1st Texas Realtors were on top of the market when I had my house up for sale. When I hired these professionals to get my house sold in August 2013…that’s exactly what happened. They did there research on the other home sales in the area and listed mine right where it needed to be. Not only did they list and sell one house but they were instrumental in the purchase of a new construction home that we purchased. From reviewing the contract and doing there own walk throughs during the construction to helping us make decisions on upgrades they both were great. Both deals were seamless and I will definitely use them for all my real estate needs.', author: 'James F.' },
  { quote: 'David and Simone Karstedt of 1st Texas Realtors have been assisting me on Real Estate deals for the last 10 years. They have handled multiple property purchases and sales. They are experienced and know the market well… and in them you’ll find a firm that you can also trust with the biggest financial moves of your life. I have peace of mind knowing that i can trust not only their judgement but that they aren’t just out to make a buck without keeping my best interests at heart.', author: 'Glen K.' },
]

export const faqs: [string, string][] = [
  ['How do I get started with buying a home?', 'Get pre-approved by a mortgage banker for the amount you want, then use our real-time MLS Home Search to explore homes for sale and rent. We guide you through offers, contingencies, addendums, and closing.'],
  ['What is a free Market Analysis?', 'We review your home, neighborhood, and recent sales to recommend a competitive price and a marketing plan — at no cost and with no obligation.'],
  ['Do you help with rentals and property management?', 'Yes. We handle real-time rental listings, tenant interviews, background checks, leases, deposits, maintenance, and repairs for owners.'],
  ['Which areas do you serve?', 'We serve Clear Lake NASA and surrounding communities including League City, Friendswood, Seabrook, Kemah, Nassau Bay, Galveston, Pearland, and more.'],
  ['Are you a full-service brokerage?', 'Family owned since 2004, we represent buyers, sellers, renters, and commercial clients with over 100 years of combined experience.'],
  ['How fast can I sell my home?', 'Every home is different, but our team regularly lists on a Friday and receives multiple offers by the end of the weekend. We price with comparable sales and market a plan tailored to your home.'],
  ['Can you help me if I am relocating to the Clear Lake area?', 'Absolutely. Relocation clients get the same full-service treatment: neighborhood guidance, school research, commute advice, virtual tours, and real-time listings across the region.'],
  ['Do you handle commercial real estate?', 'Yes — commercial property sales and leasing are part of our full-service brokerage. Contact us to discuss your commercial needs.'],
]

